<script setup lang="ts">
import { computed, ref } from 'vue'
import { ArrowDown, ArrowUp, ArrowUpDown, X } from '@lucide/vue'
import type { ResearchPageData, ResearchSeries } from './research.types'
import MarketEnvironmentChart from './MarketEnvironmentChart.vue'

const props = defineProps<{ data: ResearchPageData }>()
const period = ref<21 | 63 | 126>(63)
const expanded = ref<ResearchSeries | 'score' | null>(null)
type SortKey = 'name' | 'status' | 'sessions'
const sortKey = ref<SortKey>('name')
const sortDirection = ref<'asc' | 'desc'>('asc')
const sortedSeries = computed(() => props.data.series.slice().sort((left, right) => {
  const leftValue = sortKey.value === 'name' ? left.name : sortKey.value === 'status' ? left.status : sessions(left)
  const rightValue = sortKey.value === 'name' ? right.name : sortKey.value === 'status' ? right.status : sessions(right)
  const result = String(leftValue).localeCompare(String(rightValue), undefined, { numeric: true })
  return sortDirection.value === 'asc' ? result : -result
}))
function sortBy(key: SortKey) { if (sortKey.value === key) sortDirection.value = sortDirection.value === 'asc' ? 'desc' : 'asc'; else { sortKey.value = key; sortDirection.value = 'asc' } }
const chart = computed(() => props.data.environmentChart)
const dates = computed(() => chart.value?.dates.slice(-period.value) ?? [])
const scores = computed(() => chart.value?.score.slice(-period.value) ?? [])
const score = computed(() => chart.value?.score.at(-1) ?? 0)
const participation = computed(() => props.data.series.slice(0, 4).filter((item) => item.status === 'Healthy').length)
const trend = computed(() => props.data.series.slice(4).filter((item) => item.status === 'Healthy').length)
const displayDate = (index: number) => dates.value[index] ? new Date(`${dates.value[index]}T12:00:00Z`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' }) : ''
const sessions = (item: ResearchSeries) => Number.parseInt(item.change, 10) || 1
const history = (item: ResearchSeries) => item.points.slice(-period.value)
const expandedPoints = computed(() => expanded.value === 'score' ? scores.value : expanded.value ? history(expanded.value) : [])
function linePoints(values: number[]) {
  if (!values.length) return ''
  const min = Math.min(...values), max = Math.max(...values), span = max - min || 1
  return values.map((value, index) => `${index / Math.max(values.length - 1, 1) * 100},${94 - (value - min) / span * 88}`).join(' ')
}
</script>

<template>
  <section class="space-y-4" data-testid="market-environment-content">
    <div class="flex flex-wrap items-center justify-between gap-3"><p class="text-xs text-[var(--app-text-muted)]">Illustrative data · Index levels and component states are simulated.</p><div class="inline-flex items-center gap-0.5 rounded-md border border-[var(--app-border)] bg-[var(--app-surface-soft)] p-0.5" aria-label="Chart period"><button v-for="option in [21,63,126] as const" :key="option" type="button" class="h-7 rounded px-2.5 text-[.6875rem] font-semibold" :aria-pressed="period === option" :class="period === option ? 'bg-[var(--app-surface)] text-[var(--app-primary)] shadow-sm' : 'text-[var(--app-text-muted)] hover:text-[var(--app-primary)]'" @click="period = option">{{ option }} sessions</button></div></div>
    <div class="grid gap-3 sm:grid-cols-2 2xl:grid-cols-4"><article v-for="metric in data.metrics" :key="metric.label" class="rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] p-4 shadow-sm"><p class="text-xs text-[var(--app-text-muted)]">{{ metric.label }}</p><strong class="mt-2 block text-2xl font-semibold" :class="metric.tone === 'positive' ? 'text-[var(--app-positive)]' : metric.tone === 'negative' ? 'text-[var(--app-negative)]' : metric.tone === 'primary' ? 'text-[var(--app-primary)]' : ''">{{ metric.value }}</strong><span class="mt-1 block text-[.6875rem] leading-5 text-[var(--app-text-faint)]">{{ metric.detail }}</span></article></div>
    <div class="grid gap-4 2xl:grid-cols-[minmax(0,1fr)_290px]">
      <article class="overflow-hidden rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] shadow-sm"><header class="flex items-start justify-between gap-3 border-b border-[var(--app-border)] px-3 py-3"><div><h2 class="font-semibold">Index and Market Health</h2><p class="mt-1 text-xs text-[var(--app-text-muted)]">Compare the index with the number of healthy components.</p></div><button type="button" aria-label="Expand Healthy components chart" class="grid h-8 w-8 place-items-center rounded border border-[var(--app-border)] text-[var(--app-text-muted)] hover:text-[var(--app-primary)]" @click="expanded = 'score'">↗</button></header><div class="px-3 py-3"><div class="mb-1 flex justify-between text-xs"><strong>S&amp;P 500 Index</strong><span class="text-[var(--app-text-muted)]">Index level · simulated</span></div><MarketEnvironmentChart v-if="chart" :chart="chart" :period="period" /></div><div class="border-t border-[var(--app-border)] px-5 py-3"><div class="mb-2 flex justify-between text-[.6875rem]"><strong>Market environment</strong><span class="text-[var(--app-text-muted)]">Green = healthy · rose = unhealthy</span></div><div class="flex h-[10px] gap-0.5" role="img" :aria-label="`Market environment history, ${period} sessions`"><span v-for="(value,index) in scores" :key="index" class="min-w-0 flex-1 rounded-[1px]" :class="value >= 5 ? 'bg-[var(--app-positive)]' : 'bg-[var(--app-negative)]'" :title="`${displayDate(index)}: ${value >= 5 ? 'Healthy' : 'Unhealthy'}`" /></div></div></article>
      <aside class="space-y-4"><section class="rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] p-5"><span class="text-[.6875rem] font-bold uppercase tracking-wider text-[var(--app-text-muted)]">Composition · demo</span><strong class="mt-2 block text-4xl" :class="score >= 5 ? 'text-[var(--app-positive)]' : 'text-[var(--app-negative)]'">{{ score }}<small class="text-lg"> / 8</small></strong><span class="mt-3 inline-flex rounded-full px-3 py-1.5 text-xs font-bold" :class="score >= 5 ? 'bg-[var(--app-positive)]/10 text-[var(--app-positive)]' : 'bg-[var(--app-negative)]/10 text-[var(--app-negative)]'">{{ score >= 5 ? 'Healthy environment' : 'Unhealthy environment' }}</span><div class="mt-4 flex gap-1" role="img" :aria-label="`${score} of 8 components healthy`"><span v-for="index in 8" :key="index" class="h-3 flex-1 rounded-[2px]" :class="index <= score ? 'bg-[var(--app-positive)]' : 'bg-[var(--app-surface-muted)]'" /></div><p class="mt-3 text-xs text-[var(--app-text-muted)]">{{ score }} of 8 components are healthy. {{ 8 - score }} are unhealthy.</p><div class="mt-4 space-y-2 border-t border-[var(--app-border)] pt-3 text-xs"><div class="flex justify-between"><span>Participation</span><b>{{ participation }} / 4</b></div><div class="flex justify-between"><span>Trend conditions</span><b>{{ trend }} / 4</b></div></div></section><section class="rounded-lg border border-[var(--app-border)] bg-[var(--app-primary-soft)] p-5"><h2 class="font-semibold">Read the score</h2><div class="mt-4 space-y-4 text-xs"><div class="grid grid-cols-[48px_1fr] gap-3"><b class="text-[var(--app-positive)]">≥5</b><div><strong>Healthy</strong><p class="mt-1 text-[var(--app-text-muted)]">Five or more healthy components.</p></div></div><div class="grid grid-cols-[48px_1fr] gap-3"><b class="text-[var(--app-negative)]">&lt;5</b><div><strong>Unhealthy</strong><p class="mt-1 text-[var(--app-text-muted)]">Fewer than five healthy components.</p></div></div></div><p class="mt-4 text-xs text-[var(--app-text-muted)]">Review all eight components below to understand the score.</p></section></aside>
    </div>
    <section class="overflow-hidden rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] shadow-sm"><header class="flex flex-wrap items-center justify-between gap-3 border-b border-[var(--app-border)] px-5 py-4"><div><h2 class="font-semibold">Component Health</h2><p class="mt-1 text-xs text-[var(--app-text-muted)]">All eight components, aligned on one timeline.</p></div><div class="flex flex-wrap items-center justify-end gap-2"><span class="inline-flex items-center gap-1.5 rounded-full bg-[var(--app-positive)]/10 px-3 py-1.5 text-[.6875rem] font-bold text-[var(--app-positive)]"><i class="h-1.5 w-1.5 rounded-full bg-current"/>{{ score }} Healthy</span><span class="inline-flex items-center gap-1.5 rounded-full bg-[var(--app-negative)]/10 px-3 py-1.5 text-[.6875rem] font-bold text-[var(--app-negative)]"><i class="h-1.5 w-1.5 rounded-full bg-current"/>{{ 8 - score }} Unhealthy</span></div></header><div class="flex flex-wrap items-center justify-between gap-2 border-b border-[var(--app-border)] bg-[var(--app-primary-soft)] px-5 py-2.5 text-xs"><div class="flex gap-4"><span class="text-[var(--app-positive)]">● Healthy</span><span class="text-[var(--app-negative)]">● Unhealthy</span></div><span class="text-[var(--app-text-muted)]">Each block = one trading session · Hover for date and state · Older → Latest</span></div><div class="overflow-x-auto"><table class="w-full min-w-[900px] border-collapse text-left text-[.8125rem]"><thead class="bg-[var(--app-surface-muted)] text-[.6875rem] font-semibold text-[var(--app-text-secondary)]"><tr class="border-b border-[var(--app-border)]"><th class="px-4 py-3"><button type="button" class="inline-flex items-center gap-1.5 font-semibold" @click="sortBy('name')">Component<ArrowUp v-if="sortKey === 'name' && sortDirection === 'asc'" :size="13"/><ArrowDown v-else-if="sortKey === 'name'" :size="13"/><ArrowUpDown v-else :size="13"/></button></th><th class="px-4 py-3"><button type="button" class="inline-flex items-center gap-1.5 font-semibold" @click="sortBy('status')">Current condition<ArrowUp v-if="sortKey === 'status' && sortDirection === 'asc'" :size="13"/><ArrowDown v-else-if="sortKey === 'status'" :size="13"/><ArrowUpDown v-else :size="13"/></button></th><th class="w-[32%] min-w-[245px] max-w-[400px] px-4 py-[11px]"><div class="flex items-baseline justify-between gap-2 text-[10px] text-[var(--app-text-secondary)]"><span>Daily condition history</span><small class="whitespace-nowrap text-[9px] font-normal text-[var(--app-text-muted)]">{{ period }} sessions</small></div><div class="mt-2 flex justify-between gap-2 text-[9px] font-normal text-[var(--app-text-muted)]"><span>{{ displayDate(0) }}</span><span>{{ displayDate(Math.floor((period - 1) / 2)) }}</span><span>{{ displayDate(period - 1) }}</span></div></th><th class="px-4 py-3"><button type="button" class="inline-flex items-center gap-1.5 font-semibold" @click="sortBy('sessions')">Sessions in<br/>Current State<ArrowUp v-if="sortKey === 'sessions' && sortDirection === 'asc'" :size="13"/><ArrowDown v-else-if="sortKey === 'sessions'" :size="13"/><ArrowUpDown v-else :size="13"/></button></th><th class="w-12 px-4 py-3"></th></tr></thead><tbody><tr v-for="(item,rowIndex) in sortedSeries" :key="item.name" class="border-b border-[var(--app-border-muted)] last:border-0 hover:bg-[var(--app-surface-hover)]" :class="rowIndex % 2 ? 'bg-[var(--app-row-even)]' : ''"><td class="px-4 py-3 font-semibold text-[var(--app-text-secondary)]"><button type="button" class="text-left hover:text-[var(--app-primary)]" @click="expanded = item">{{ item.name }}</button></td><td class="px-4 py-3"><span class="inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[.6875rem] font-bold" :class="item.status === 'Healthy' ? 'bg-[var(--app-positive)]/10 text-[var(--app-positive)]' : 'bg-[var(--app-negative)]/10 text-[var(--app-negative)]'"><i class="h-1.5 w-1.5 rounded-full bg-current"/>{{ item.status }}</span></td><td class="w-[32%] min-w-[245px] max-w-[400px] px-4 py-[11px]"><div class="flex h-[10px] min-w-0 gap-0.5" role="img" :aria-label="`${item.name} daily condition history`"><span v-for="(value,index) in history(item)" :key="index" class="relative min-w-0 flex-1 rounded-[1px] transition-opacity hover:z-10 hover:outline hover:outline-1 hover:outline-offset-1 hover:outline-[var(--app-text)]" :class="value ? 'bg-[var(--app-positive)]' : 'bg-[var(--app-negative)]'" :title="`${displayDate(index)}: ${value ? 'Healthy' : 'Unhealthy'}`" /></div></td><td class="whitespace-nowrap px-4 py-3 text-[var(--app-text-muted)]">{{ sessions(item) }} {{ sessions(item) === 1 ? 'session' : 'sessions' }}</td><td class="px-4 py-3 text-right"><button type="button" :aria-label="`Expand ${item.name}`" class="h-6 w-6 rounded border border-[var(--app-border)] bg-[var(--app-surface)] text-sm leading-5 text-[var(--app-text-muted)] hover:bg-[var(--app-primary-soft)] hover:text-[var(--app-primary)]" @click="expanded = item">↗</button></td></tr></tbody></table></div><footer class="border-t border-[var(--app-border)] bg-[var(--app-surface-soft)] px-5 py-3 text-xs text-[var(--app-text-muted)]">Demo data. Each healthy component contributes one point; the eight component states add up to the displayed score.</footer></section>
    <Teleport to="body"><div v-if="expanded" class="fixed inset-0 z-[80] grid place-items-center bg-[var(--app-overlay)] p-4" role="dialog" aria-modal="true" :aria-label="expanded === 'score' ? 'Healthy components' : expanded.name"><section class="w-full max-w-5xl overflow-hidden rounded-lg border border-[var(--app-border)] bg-[var(--app-surface)] shadow-2xl"><header class="flex items-center justify-between border-b border-[var(--app-border)] px-5 py-4"><div><p class="text-[.6875rem] font-bold uppercase tracking-wider text-[var(--app-text-muted)]">Research detail</p><h2 class="mt-1 text-lg font-semibold">{{ expanded === 'score' ? 'Healthy components' : expanded.name }}</h2></div><button type="button" aria-label="Close expanded chart" class="grid h-9 w-9 place-items-center rounded-md hover:bg-[var(--app-surface-hover)]" @click="expanded = null"><X :size="18" /></button></header><div class="p-6"><svg viewBox="0 0 100 100" class="h-[55vh] min-h-72 w-full" preserveAspectRatio="none"><line v-for="y in [20,40,60,80]" :key="y" x1="0" :y1="y" x2="100" :y2="y" stroke="var(--chart-grid)" stroke-width=".4" /><polyline :points="linePoints(expandedPoints)" fill="none" stroke="var(--app-primary)" stroke-width="1.8" vector-effect="non-scaling-stroke" /></svg></div><footer class="border-t border-[var(--app-border)] bg-[var(--app-surface-soft)] px-5 py-3 text-xs text-[var(--app-text-muted)]">{{ period }} sessions · Static preview data</footer></section></div></Teleport>
  </section>
</template>
